PAY.response:
status = 200
  ? (body.status = "SUCCESS" and $type(body.ocsRef) = "string" and body.ocsRef != ""
      ? {"outcome": "SUCCESS", "partnerRef": body.ocsRef, "code": body.code}
      : {"outcome": "UNKNOWN", "reason": "MALFORMED_REPLY"})
: status = 422
  ? ($type(body.code) = "string" and body.code != ""
      ? {"outcome": "FAILED", "code": body.code, "message": body.message}
      : {"outcome": "UNKNOWN", "reason": "MALFORMED_REPLY"})
: status = 400
  ? {"outcome": "FAILED", "code": "HTTP_400", "message": body.message}
: {"outcome": "UNKNOWN", "reason": "UNEXPECTED_STATUS"}

STATUS_QUERY.response:
status = 200
  ? (body.status = "SUCCESS" and $type(body.ocsRef) = "string" and body.ocsRef != ""
      ? {"outcome": "SUCCESS", "partnerRef": body.ocsRef, "code": body.code}
      : body.status = "FAILED" and $type(body.code) = "string" and body.code != ""
        ? {"outcome": "FAILED", "code": body.code, "message": body.message}
        : {"outcome": "UNKNOWN", "reason": "MALFORMED_REPLY"})
: status = 404 and body.status = "NOT_FOUND"
  ? {"outcome": "NOT_FOUND", "code": body.code, "message": body.message}
: {"outcome": "UNKNOWN", "reason": "UNEXPECTED_STATUS"}
